import json, math
AGES=[0.,4.,5.,8.,12.,20.,24.,36.,48.]
XC=.5
Q0S=[('zero',0.),('A_proxy',.0148724491091024),('B_proxy',.0138090880510916)]
def x_at(t,alpha,tau,r,dur,x0=0.):
    if t<=dur: return x0*math.exp(-t/tau)+alpha*r*tau*(1-math.exp(-t/tau))
    xd=x0*math.exp(-dur/tau)+alpha*r*tau*(1-math.exp(-dur/tau))
    return xd*math.exp(-(t-dur)/tau)
def crossing(alpha,tau,r,dur,x0=0.):
    # Only report an upward crossing from below or an equality with positive derivative.
    if abs(x0-XC)<1e-14:
        return 0. if alpha*r-x0/tau>0 else None
    if x0>XC: return None
    xs=alpha*r*tau
    if xs<=XC: return None
    tc=-tau*math.log((xs-XC)/(xs-x0))
    return tc if tc<=dur+1e-12 else None
def trajectory(alpha,tau,kn,kd,r,dur,q0):
    tc=crossing(alpha,tau,r,dur,0.)
    # Starting below threshold, source is identically zero before tc; crossing freezes q.
    vals=[]
    for t in AGES:
        q=q0*math.exp(-kd*min(t,tc)) if tc is not None else q0*math.exp(-kd*t)
        vals.append({'time_h':t,'x':x_at(t,alpha,tau,r,dur),'q':q,'production_on':t<dur})
    atcross=None if tc is None else {'time_h':tc,'x':XC,'q':q0*math.exp(-kd*tc),'q_before':q0*math.exp(-kd*max(0.,tc-1e-6)),'q_after':q0*math.exp(-kd*tc)}
    return {'crossing':atcross,'shutoff':{'time_h':dur,'x':x_at(dur,alpha,tau,r,dur),'q':q0*math.exp(-kd*min(dur,tc)) if tc is not None else q0*math.exp(-kd*dur)},'observations':vals}
